from datetime import datetime

# Independent recomputation using filename-based grouping
files = sorted(glob.glob('/app/logs/*.log'))
sev_by_file = {}
for f in files:
    m = re.match(r'/app/logs/(\d{4}-\d{2}-\d{2})_(.+)\.log$', f)
    d = m.group(1)
    cnt = {}
    with open(f) as fh:
        for line in fh:
            s = re.search(r'\[(ERROR|WARNING|INFO|DEBUG)\]', line).group(1)
            cnt[s] = cnt.get(s, 0) + 1
    sev_by_file[d] = cnt

def sum_range(ds):
    out = {"ERROR":0,"WARNING":0,"INFO":0}
    for d in ds:
        for s in out:
            out[s] += sev_by_file.get(d, {}).get(s, 0)
    return out

def dates(a, b):
    da = datetime.strptime(a, "%Y-%m-%d").date(); db = datetime.strptime(b, "%Y-%m-%d").date()
    r=[]; d=da
    while d<=db: r.append(d.strftime("%Y-%m-%d")); d+=timedelta(days=1)
    return r

today = sum_range(["2025-08-12"])
last7 = sum_range(dates("2025-08-06","2025-08-12"))
